#!/system/bin/sh
# moresampler2.sh - self-contained moresampler2 (aarch64) launcher.
# The binary is embedded below as base64 and unpacked on first run.
EXPECT=330480
SELF="$0"
DIR="$(cd "$(dirname "$0")" 2>/dev/null && pwd)"
BIN=""
for d in "$DIR" "$TMPDIR" "$HOME" /data/local/tmp /tmp; do
  [ -n "$d" ] && [ -d "$d" ] && [ -w "$d" ] || continue
  cand="$d/.moresampler2.bin"
  if [ -x "$cand" ] && [ "$(wc -c < "$cand")" = "$EXPECT" ]; then BIN="$cand"; break; fi
  if sed '1,/^__PAYLOAD__$/d' "$SELF" | base64 -d > "$cand.tmp" 2>/dev/null \
     && [ "$(wc -c < "$cand.tmp")" = "$EXPECT" ]; then
    chmod 755 "$cand.tmp" && mv -f "$cand.tmp" "$cand" && BIN="$cand" && break
  fi
  rm -f "$cand.tmp"
done
if [ -z "$BIN" ]; then
  echo "moresampler2.sh: could not unpack the binary (no writable folder or base64 missing)" >&2
  exit 1
fi
exec "$BIN" "$@"
